CREATE TABLE public."announcements" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "text" text NOT NULL, "active" boolean DEFAULT true NOT NULL, "tone" text DEFAULT 'gold' NOT NULL, "createdAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."careers" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "playerId" integer NOT NULL, "teamName" text NOT NULL, "fromYear" integer NOT NULL, "toYear" integer);
CREATE TABLE public."comments" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "targetType" text NOT NULL, "targetId" integer NOT NULL, "name" text NOT NULL, "body" text NOT NULL, "status" text DEFAULT 'pending' NOT NULL, "userId" integer, "mediaUrl" text DEFAULT '' NOT NULL, "parentId" integer, "editedAt" timestamp, "createdAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."conversation_members" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "conversationId" integer NOT NULL, "userId" integer NOT NULL, "role" text DEFAULT 'member' NOT NULL, "lastReadAt" timestamp DEFAULT now() NOT NULL, "joinedAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."conversations" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "kind" text DEFAULT 'direct' NOT NULL, "title" text DEFAULT '' NOT NULL, "description" text DEFAULT '' NOT NULL, "avatarUrl" text DEFAULT '' NOT NULL, "ownerId" integer, "inviteToken" text DEFAULT '' NOT NULL, "poll" jsonb, "createdAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."follows" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "followerId" integer NOT NULL, "followingId" integer NOT NULL, "createdAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."friend_requests" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "fromId" integer NOT NULL, "toId" integer NOT NULL, "status" text DEFAULT 'pending' NOT NULL, "createdAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."gallery" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "teamId" integer NOT NULL, "type" text DEFAULT 'image' NOT NULL, "url" text NOT NULL, "caption" text NOT NULL);
CREATE TABLE public."highlights" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "userId" integer NOT NULL, "title" text NOT NULL, "coverUrl" text DEFAULT '' NOT NULL, "storyIds" jsonb DEFAULT '[]'::jsonb NOT NULL, "createdAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."interactions" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "targetType" text NOT NULL, "targetId" integer NOT NULL, "userId" integer NOT NULL, "kind" text NOT NULL, "createdAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."invites" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "token" text NOT NULL, "teamId" integer NOT NULL, "used" boolean DEFAULT false NOT NULL, "expiresAt" timestamp NOT NULL, CONSTRAINT "invites_token_unique" UNIQUE("token"));
CREATE TABLE public."lineups" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "matchId" integer NOT NULL, "teamId" integer NOT NULL, "formation" text DEFAULT '4-3-3' NOT NULL, "published" boolean DEFAULT false NOT NULL, "positions" jsonb DEFAULT '[]'::jsonb NOT NULL);
CREATE TABLE public."match_events" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "matchId" integer NOT NULL, "teamId" integer NOT NULL, "playerId" integer, "assistId" integer, "type" text NOT NULL, "minute" integer NOT NULL);
CREATE TABLE public."matches" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "homeId" integer NOT NULL, "awayId" integer NOT NULL, "tournamentId" integer, "date" text NOT NULL, "time" text NOT NULL, "stadium" text NOT NULL, "referee" text DEFAULT '' NOT NULL, "status" text DEFAULT 'scheduled' NOT NULL, "homeScore" integer DEFAULT 0 NOT NULL, "awayScore" integer DEFAULT 0 NOT NULL, "minute" integer DEFAULT 0 NOT NULL, "penaltyHome" integer, "penaltyAway" integer, "round" text DEFAULT '' NOT NULL, "stage" text DEFAULT 'league' NOT NULL, "group" text DEFAULT '' NOT NULL, "bracketSlot" integer, "refereeId" integer, "report" text DEFAULT '' NOT NULL, "views" integer DEFAULT 0 NOT NULL);
CREATE TABLE public."message_reads" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "messageId" integer NOT NULL, "userId" integer NOT NULL, "readAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."messages" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "conversationId" integer NOT NULL, "userId" integer NOT NULL, "text" text DEFAULT '' NOT NULL, "mediaType" text DEFAULT '' NOT NULL, "mediaUrl" text DEFAULT '' NOT NULL, "replyTo" integer, "editedAt" timestamp, "createdAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."motm_votes" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "matchId" integer NOT NULL, "playerId" integer NOT NULL, "voterId" text NOT NULL);
CREATE TABLE public."news" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "title" text NOT NULL, "excerpt" text NOT NULL, "body" text NOT NULL, "image" text NOT NULL, "category" text NOT NULL, "teamId" integer, "createdAt" timestamp DEFAULT now() NOT NULL, "views" integer DEFAULT 0 NOT NULL);
CREATE TABLE public."notes" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "userId" integer NOT NULL, "text" text NOT NULL, "durationHours" integer DEFAULT 1 NOT NULL, "createdAt" timestamp DEFAULT now() NOT NULL, "expiresAt" timestamp NOT NULL);
CREATE TABLE public."notifications" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "userId" integer NOT NULL, "actorId" integer, "kind" text NOT NULL, "text" text NOT NULL, "href" text DEFAULT '/' NOT NULL, "read" boolean DEFAULT false NOT NULL, "createdAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."pinned_messages" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "conversationId" integer NOT NULL, "messageId" integer NOT NULL);
CREATE TABLE public."players" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "teamId" integer, "name" text NOT NULL, "age" integer NOT NULL, "position" text NOT NULL, "number" integer NOT NULL, "photo" text DEFAULT '' NOT NULL, "bio" text DEFAULT '' NOT NULL);
CREATE TABLE public."poll_votes" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "pollId" integer NOT NULL, "optionId" integer NOT NULL, "voterId" text NOT NULL);
CREATE TABLE public."polls" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "question" text NOT NULL, "description" text DEFAULT '' NOT NULL, "active" boolean DEFAULT true NOT NULL, "options" jsonb DEFAULT '[]'::jsonb NOT NULL);
CREATE TABLE public."posts" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "userId" integer NOT NULL, "type" text DEFAULT 'text' NOT NULL, "body" text DEFAULT '' NOT NULL, "mediaType" text DEFAULT '' NOT NULL, "mediaUrl" text DEFAULT '' NOT NULL, "media_urls" jsonb DEFAULT '[]'::jsonb NOT NULL, "hashtags" jsonb DEFAULT '[]'::jsonb NOT NULL, "pollOptions" jsonb DEFAULT '[]'::jsonb NOT NULL, "pollVoters" jsonb DEFAULT '{}'::jsonb NOT NULL, "privacy" text DEFAULT 'public' NOT NULL, "audience" jsonb DEFAULT '[]'::jsonb NOT NULL, "teamId" integer, "matchId" integer, "repostOf" integer, "status" text DEFAULT 'approved' NOT NULL, "editedAt" timestamp, "createdAt" timestamp DEFAULT now() NOT NULL, "views" integer DEFAULT 0 NOT NULL);
CREATE TABLE public."referees" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" text NOT NULL, "phone" text DEFAULT '' NOT NULL, "userId" integer, "photo" text DEFAULT '' NOT NULL, "badgeNumber" text DEFAULT '' NOT NULL, "officialStatus" text DEFAULT 'official' NOT NULL, "leagueName" text DEFAULT 'دوري الناصرية الشعبي' NOT NULL, CONSTRAINT "referees_userId_unique" UNIQUE("userId"));
CREATE TABLE public."seasons" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" text NOT NULL, "description" text DEFAULT '' NOT NULL, "active" boolean DEFAULT false NOT NULL, "summary" jsonb DEFAULT '[]'::jsonb NOT NULL, "createdAt" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."sessions" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "tokenHash" text NOT NULL, "userId" integer NOT NULL, "expiresAt" timestamp NOT NULL, CONSTRAINT "sessions_tokenHash_unique" UNIQUE("tokenHash"));
CREATE TABLE public."site_settings" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "social" jsonb DEFAULT '{}'::jsonb NOT NULL, "labels" jsonb DEFAULT '{}'::jsonb NOT NULL, "moderation" jsonb DEFAULT '{"posts":false,"stories":false,"comments":true}'::jsonb NOT NULL, "privacy" jsonb DEFAULT '{"followerLists":"logged"}'::jsonb NOT NULL, "branding" jsonb DEFAULT '{}'::jsonb NOT NULL);
CREATE TABLE public."stories" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "userId" integer NOT NULL, "type" text DEFAULT 'image' NOT NULL, "url" text NOT NULL, "caption" text DEFAULT '' NOT NULL, "durationHours" integer DEFAULT 24 NOT NULL, "viewers" jsonb DEFAULT '[]'::jsonb NOT NULL, "archived" boolean DEFAULT false NOT NULL, "status" text DEFAULT 'approved' NOT NULL, "createdAt" timestamp DEFAULT now() NOT NULL, "expiresAt" timestamp NOT NULL);
CREATE TABLE public."teams" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" text NOT NULL, "shortName" text NOT NULL, "neighborhood" text NOT NULL, "founded" integer DEFAULT 2020 NOT NULL, "stadium" text NOT NULL, "manager" text NOT NULL, "color" text DEFAULT '#63dda2' NOT NULL, "awayColor" text DEFAULT '#ffffff' NOT NULL, "emblem" text DEFAULT 'shield' NOT NULL, "bio" text DEFAULT '' NOT NULL, "achievements" jsonb DEFAULT '[]'::jsonb NOT NULL, "logo" text DEFAULT '' NOT NULL, "approved" boolean DEFAULT false NOT NULL, "views" integer DEFAULT 0 NOT NULL);
CREATE TABLE public."tournaments" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" text NOT NULL, "format" text DEFAULT 'league' NOT NULL, "season" text DEFAULT '2026' NOT NULL, "team_ids" jsonb DEFAULT '[]'::jsonb NOT NULL, "status" text DEFAULT 'active' NOT NULL, "startDate" text NOT NULL, "description" text DEFAULT '' NOT NULL, "sourceTournamentId" integer, "qualifiers" integer DEFAULT 0 NOT NULL, "qualificationRule" text DEFAULT 'top' NOT NULL, "seasonLabel" text DEFAULT '' NOT NULL);
CREATE TABLE public."typing_signals" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "conversationId" integer NOT NULL, "userId" integer NOT NULL, "at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE public."users" ("id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "name" text NOT NULL, "email" text NOT NULL, "username" text DEFAULT '' NOT NULL, "passwordHash" text DEFAULT '' NOT NULL, "authId" uuid UNIQUE, "role" text DEFAULT 'fan' NOT NULL, "teamId" integer, "avatar" text DEFAULT '' NOT NULL, "bio" text DEFAULT '' NOT NULL, "socials" jsonb DEFAULT '{}'::jsonb NOT NULL, "verified" boolean DEFAULT false NOT NULL, "banned" boolean DEFAULT false NOT NULL, "restrictedUntil" timestamp, "mutedUntil" timestamp, "showFollowers" boolean DEFAULT true NOT NULL, "badge" text DEFAULT '' NOT NULL, "badgeTeamId" integer, "verifiedAt" timestamp, "verifiedNote" text DEFAULT '' NOT NULL, "verifiedById" integer, "permissions" jsonb DEFAULT '{}'::jsonb NOT NULL, "preferences" jsonb DEFAULT '{"favoriteTeams":[],"favoritePlayers":[],"settings":{}}'::jsonb NOT NULL, "createdAt" timestamp DEFAULT now() NOT NULL, CONSTRAINT "users_email_unique" UNIQUE("email"), CONSTRAINT "users_username_unique" UNIQUE("username"));

