-- All app reads/writes go through the app server (service role), which enforces the app's own permission rules.
GRANT ALL ON public."announcements", public."careers", public."comments", public."conversation_members", public."conversations", public."follows", public."friend_requests", public."gallery", public."highlights", public."interactions", public."invites", public."lineups", public."match_events", public."matches", public."message_reads", public."messages", public."motm_votes", public."news", public."notes", public."notifications", public."pinned_messages", public."players", public."poll_votes", public."polls", public."posts", public."referees", public."seasons", public."sessions", public."site_settings", public."stories", public."teams", public."tournaments", public."typing_signals", public."users" TO service_role;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['announcements','careers','comments','conversation_members','conversations','follows','friend_requests','gallery','highlights','interactions','invites','lineups','match_events','matches','message_reads','messages','motm_votes','news','notes','notifications','pinned_messages','players','poll_votes','polls','posts','referees','seasons','sessions','site_settings','stories','teams','tournaments','typing_signals','users'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION public.app_exec(q text, mode text)
RETURNS json
LANGUAGE plpgsql
SET search_path = public
AS $fn$
DECLARE res json;
BEGIN
  IF mode = 'array' THEN
    EXECUTE format('WITH t AS (%s) SELECT coalesce(json_agg((SELECT json_agg(e.value) FROM json_each(row_to_json(t)) e)), ''[]''::json) FROM t', q) INTO res;
  ELSIF mode = 'object' THEN
    EXECUTE format('WITH t AS (%s) SELECT coalesce(json_agg(row_to_json(t)), ''[]''::json) FROM t', q) INTO res;
  ELSE
    EXECUTE q;
    res := '[]'::json;
  END IF;
  RETURN res;
END;
$fn$;
REVOKE ALL ON FUNCTION public.app_exec(text, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.app_exec(text, text) TO service_role;